using System.Collections.Generic;
using Newtonsoft.Json;

namespace Codebase.Simulation.Harness
{
	// Request fields of the differential probes (design 3.4; unit C2). A job with "probes" runs the
	// edit-mode probes (ED/SimulationProbes.cs) before it enters Play and the Play-mode probes
	// (SimulationRuntimeProbes) when it finishes. The input grid is generated by Python
	// (tufu_balance.unity.probes) and committed; "input" is relative to the repository root of the
	// worktree Unity runs in and must hash to "input_sha256".
	public partial class SimulationRunRequest
	{
		public partial class Job
		{
			[JsonProperty("probes")] public ProbeOptions Probes;
		}

		[JsonObject(MemberSerialization.OptIn)]
		public partial class ProbeOptions
		{
			[JsonProperty("input", Required = Required.Always)] public string Input;
			[JsonProperty("input_sha256", Required = Required.Always)] public string InputSha256;
			[JsonProperty("edit")] public List<string> Edit = new List<string>();
			[JsonProperty("runtime")] public List<string> Runtime = new List<string>();
		}
	}
}
